/** Sequential line transport for the existing primary exchange. No action queue. */
import {createInterface} from 'node:readline';
import {readFile} from 'node:fs/promises';
import {pathToFileURL} from 'node:url';
import {createInstrumentedRelayClient} from './relay_host.mjs';
import {createPrimaryExchange} from './primary_exchange.mjs';

const schema='agent-interface/primary-stdio-v1';
const object=value=>value&&typeof value==='object'&&!Array.isArray(value);
const fields=(value,allowed)=>Object.keys(value).every(key=>allowed.includes(key));
export function validatePrimaryConfig(config) {
  if(!object(config)||!fields(config,['host','route','exchangeDirectory','expectations','primaryOptions'])||
    !['guarded-local','direct-post'].includes(config.route)||
    typeof config.exchangeDirectory!=='string'||!config.exchangeDirectory.trim()||
    !object(config.host)||!fields(config.host,['command','args','evidenceDirectory','minimumEvidenceFreeBytes','reuseReviewedImages'])||
    typeof config.host.command!=='string'||!config.host.command.trim()||
    !Array.isArray(config.host.args)||!Array.from(config.host.args).every(arg=>typeof arg==='string')||
    typeof config.host.evidenceDirectory!=='string'||!config.host.evidenceDirectory.trim()||
    (config.expectations!==undefined&&!Array.isArray(config.expectations))||
    (config.primaryOptions!==undefined&&(!object(config.primaryOptions)||!fields(config.primaryOptions,['observationArguments','reviewWindowId']))) )
    throw TypeError('explicit primary route, host, fresh directories and known configuration fields required');
  return config;
}

function emit(output,value) {
  return new Promise((resolve,reject)=>{
    try {output.write(JSON.stringify(value)+'\n',error=>error?reject(error):resolve());}
    catch(error){reject(error);}
  });
}

export async function servePrimaryLines({exchange,input,output}) {
  const lines=createInterface({input,terminal:false});
  let pending=null,failure=null;
  const rejectedWrites=new Set();
  function failed(error) {failure??=error;input.pause();lines.close();}
  output.on('error',failed);
  input.on('error',failed);
  async function perform(line) {
    let request;
    try {request=JSON.parse(line);}
    catch(error){
      await emit(output,{schema,status:'refused',operation_invoked:false,
        next_id:exchange.state().next_id,error:String(error)});return;
    }
    let result;
    try {result=await exchange.execute(request);}
    catch(error){
      await emit(output,{schema,status:'command_error',error:String(error),
        // Correlation only: next_id may be unchanged for envelope rejection or
        // advanced for a consumed command. Neither field authorizes replay.
        command_id:Number.isSafeInteger(request?.id)?request.id:null,
        command_method:typeof request?.method==='string'&&request.method.length<=64?request.method:null,
        replay_allowed:false,state:exchange.state()});return;
    }
    await emit(output,{schema,status:'returned',result});
  }
  return new Promise((resolve,reject)=>{
    lines.on('line',line=>{
      if(failure)return;
      if(pending){
        // Refuse this line now. It is never retained as a future action.
        const write=emit(output,{schema,status:'busy',operation_invoked:false,
          pending:true,next_id:exchange.state().next_id}).catch(failed);
        rejectedWrites.add(write);write.finally(()=>rejectedWrites.delete(write));return;
      }
      pending=perform(line).catch(failed).finally(()=>{pending=null;});
    });
    lines.once('close',()=>{
      (async()=>{
        // EOF or a broken output channel does not cancel a committed command.
        // Finish observing that same promise before owner transport cleanup.
        await pending;await Promise.all(rejectedWrites);
        output.removeListener('error',failed);input.removeListener('error',failed);
        if(failure)reject(failure);else resolve();
      })().catch(reject);
    });
  });
}

export async function runPrimaryStdio(config,{input=process.stdin,output=process.stdout}={}) {
  validatePrimaryConfig(config);
  if(output.isTTY)throw TypeError('primary stdout must be a pipe or file; terminal rendering is not a JSON-lines transport');
  const host=await createInstrumentedRelayClient(config.host);
  let exchange,failure=null;
  try {
    exchange=await createPrimaryExchange({host,route:config.route,directory:config.exchangeDirectory,
      expectations:config.expectations??[],options:config.primaryOptions??{}});
    await emit(output,{schema,status:'ready',state:exchange.state()});
    await servePrimaryLines({exchange,input,output});
  } catch(error){failure=error;}
  // Close only the original transport after EOF/failure. A failed output must
  // not be written again in a finally block that hides its original exception.
  let exit;
  try {exit=await host.close();}
  catch(error){
    if(failure)throw new AggregateError([failure,error],'primary stream and transport cleanup failed');
    throw error;
  }
  if(failure)throw failure;
  await emit(output,{schema,status:'terminal',exit,state:exchange.state()});
}

if(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href) {
  try {
    if(process.argv.length!==4||process.argv[2]!=='--config')
      throw TypeError('Usage: node primary_stdio.mjs --config /absolute/config.json');
    await runPrimaryStdio(JSON.parse(await readFile(process.argv[3],'utf8')));
  } catch(error){console.error(String(error));process.exitCode=2;}
}

/** Explicit sequential primary commands with original file presentation.
 * No action policy, queue, retry, implicit review, transport startup or cleanup.
 */
import {mkdir, writeFile} from 'node:fs/promises';
import {resolve, join} from 'node:path';
import {createHash} from 'node:crypto';
import {createPrimaryCaller} from './primary_caller.mjs';

const methods=new Set(['call','observe','mint','mintMany','input','inputWithFeedback',
  'reviewWindow','review','acknowledgeText','presentOriginal']);
const snapshot=value=>JSON.parse(JSON.stringify(value,(_key,item)=>{
  if(item===undefined||typeof item==='function'||typeof item==='symbol'||
    (typeof item==='number'&&!Number.isFinite(item)))throw TypeError('finite JSON required');
  return item;
}));

export async function createPrimaryExchange({host,directory,route,expectations=[],options={}}) {
  if(!['guarded-local','direct-post'].includes(route))throw TypeError('explicit supported route required');
  if(typeof directory!=='string'||!directory.trim())throw TypeError('fresh exchange directory required');
  const path=resolve(directory);
  // Caller-owned existing parent; never reuse an occupied directory.
  await mkdir(path);
  let nextId=1,busy=false,stopped=null,current=null;
  const sinks={
    text:async value=>{
      if(!current)throw Error('presentation outside command');
      current.presented_text.push(snapshot(value));
    },
    image:async ({bytes,mimeType})=>{
      if(!current)throw Error('presentation outside command');
      if(mimeType!=='image/png'||!Buffer.isBuffer(bytes)||!bytes.length)
        throw TypeError('original nonempty PNG bytes required');
      const copy=Buffer.from(bytes);
      const imagePath=join(path,`image-${current.id}-${current.images.length+1}.png`);
      await writeFile(imagePath,copy,{flag:'wx'});
      current.images.push({path:imagePath,mime_type:mimeType,bytes:copy.length,
        sha256:createHash('sha256').update(copy).digest('hex')});
    }
  };
  const primary=createPrimaryCaller(host,route,sinks,expectations,options);
  return {
    state:()=>({next_id:nextId,busy,stopped,caller_state:primary.state()}),
    async execute(command) {
      if(busy)throw Error('command outstanding; wait, do not queue or resend');
      const request=snapshot(command);
      if(!request||typeof request!=='object'||Array.isArray(request)||
        Object.keys(request).sort().join(',')!=='args,id,method'||
        !Number.isSafeInteger(request.id)||request.id!==nextId)
        throw TypeError(`next command id must be ${nextId}; exact id/method/args envelope required`);
      if(!methods.has(request.method)||!Array.isArray(request.args))throw TypeError('known method and positional args required');
      const closing=request.method==='call'&&request.args.length===2&&
        request.args[0]==='interface_close'&&request.args[1]&&
        typeof request.args[1]==='object'&&!Array.isArray(request.args[1])&&
        Object.keys(request.args[1]).length===0;
      if(stopped&&!closing)throw Error('exchange stopped: '+stopped);
      busy=true;nextId++;
      current={id:request.id,method:request.method,presented_text:[],images:[]};
      try {
        // Consume once before persistence/dispatch, even on ambiguous failure.
        await writeFile(join(path,`request-${request.id}.json`),JSON.stringify(request)+'\n',{flag:'wx'});
        const reply=await primary[request.method](...request.args);
        const originalReplyPath=join(path,`original-reply-${request.id}.json`);
        await writeFile(originalReplyPath,JSON.stringify(reply??null)+'\n',{flag:'wx'});
        const result={...current,attempt:reply?.attempt??null,
          original_reply_path:originalReplyPath,caller_state:primary.state(),next_id:nextId};
        await writeFile(join(path,`presentation-${request.id}.json`),JSON.stringify(result)+'\n',{flag:'wx'});
        return result;
      } catch(error) {
        stopped??=String(error)+'; inspect retained original files; never replay input';
        // Evidence errors are not repaired by a second action. The caller owns
        // transport lifetime and can explicitly attempt public close once.
        throw error;
      } finally {current=null;busy=false;}
    }
  };
}

// Opt-in sequential primary caller policy; not runtime input authority.
export function createPrimaryCaller(host, route, sinks, expectations = [], options = {}) {
  const controls = new Map(expectations.map(e => [e.id, structuredClone(e)]));
  if (controls.size !== expectations.length) throw Error('duplicate control id');
  const consumed = new Set();
  const observationArguments = route === 'guarded-local' ? {} :
    structuredClone(options.observationArguments);
  const reviewWindowId = options.reviewWindowId;
  const canonical = value => JSON.stringify(value, (_key, v) => v && typeof v === 'object' && !Array.isArray(v)
    ? Object.fromEntries(Object.keys(v).sort().map(k => [k,v[k]])) : v);
  const tools = new Set(['interface_clock', 'interface_close', 'interface_results',
    'interface_validate', ...(route === 'guarded-local'
      ? ['interface_guarded_observe', 'interface_guarded_mint', 'interface_guarded_mint_many',
        'interface_guarded_input', 'interface_guarded_review_window']
      : ['interface_observe', 'interface_dispatch',
        'interface_inspect_target', 'interface_review_target'])]);
  let stopped = null;
  function stop(reason) { stopped ??= reason; }
  function read(reply) {
    const text = reply.result.content.find(c => c.type === 'text')?.text;
    if (typeof text !== 'string') throw TypeError('missing response JSON text');
    const meta = JSON.parse(text);
    if (!meta || typeof meta !== 'object' || Array.isArray(meta)) {
      throw TypeError('response metadata must be an object');
    }
    return meta;
  }
  function inputArguments(values) {
    const [alias, offset, interaction, tail] = values;
    if (route !== 'guarded-local' || values.length !== 4 ||
        typeof alias !== 'string' || !alias.trim() ||
        !Array.isArray(offset) || offset.length !== 2 ||
        !Array.from(offset).every(Number.isSafeInteger) ||
        !['click', 'keyboard', 'move'].includes(interaction) || !Array.isArray(tail)) {
      stop('invalid primary input arguments');
      throw TypeError(stopped);
    }
    let copiedTail;
    try { copiedTail = structuredClone(tail); }
    catch (error) { stop('invalid primary input tail'); throw error; }
    return { alias, offset: [...offset], interaction, tail: copiedTail,
      detail: 'brief', observation_refs: true };
  }
  const caller = {
    state: () => ({ stopped }),
    async input(...values) {
      return caller.call('interface_guarded_input', inputArguments(values));
    },
    async inputWithFeedback(...values) {
      let policy;
      try { policy = structuredClone(values[4]); }
      catch (error) { stop('invalid primary feedback policy'); throw error; }
      if (values.length !== 5 || !policy || typeof policy !== 'object' || Array.isArray(policy) ||
          Object.keys(policy).some(key => !['expected_title','rejected_titles','timeout_ms'].includes(key)) ||
          typeof policy.expected_title !== 'string' || policy.expected_title.length === 0 ||
          (policy.rejected_titles !== undefined && (!Array.isArray(policy.rejected_titles) ||
            !Array.from(policy.rejected_titles).every(title => typeof title === 'string' && title.length && title !== policy.expected_title))) ||
          (policy.timeout_ms !== undefined && (!Number.isSafeInteger(policy.timeout_ms) || policy.timeout_ms < 0 || policy.timeout_ms > 10000))) {
        stop('invalid primary feedback policy');
        throw TypeError(stopped);
      }
      const args = inputArguments(values.slice(0,4));
      args.feedback = { expected_title: policy.expected_title,
        rejected_titles: [...(policy.rejected_titles ?? [])], timeout_ms: policy.timeout_ms ?? 2000 };
      return caller.call('interface_guarded_input', args);
    },
    async reviewWindow(...unexpected) {
      if (route !== 'guarded-local' || unexpected.length ||
          !Number.isSafeInteger(reviewWindowId) || reviewWindowId < 1) {
        stop('invalid primary window review configuration or arguments');
        throw TypeError(stopped);
      }
      return caller.call('interface_guarded_review_window', { window_id: reviewWindowId });
    },
    async mint(...values) {
      const [alias, sourceSequence, point, regionSize] = values;
      const pair = value => Array.isArray(value) && value.length === 2 &&
        value.every(Number.isSafeInteger);
      if (route !== 'guarded-local' || values.length !== 4 ||
          typeof alias !== 'string' || !alias.trim() ||
          !Number.isSafeInteger(sourceSequence) || sourceSequence < 1 ||
          !pair(point) || !pair(regionSize) || regionSize.some(v => v < 4 || v > 96)) {
        stop('invalid primary mint arguments');
        throw TypeError(stopped);
      }
      return caller.call('interface_guarded_mint', {
        alias, source_sequence: sourceSequence,
        point: [...point], region_size: [...regionSize]
      });
    },
    async mintMany(...values) {
      const [sourceSequence, references] = values;
      const pair = value => Array.isArray(value) && value.length === 2 &&
        Array.from(value).every(Number.isSafeInteger);
      const validReference = reference => reference && typeof reference === 'object' &&
        !Array.isArray(reference) &&
        Object.keys(reference).sort().join(',') === 'alias,point,region_size' &&
        typeof reference.alias === 'string' && /^[a-z][a-z0-9_]{0,31}$/.test(reference.alias) &&
        pair(reference.point) && pair(reference.region_size) &&
        reference.region_size.every(value => value >= 4 && value <= 96);
      if (route !== 'guarded-local' || values.length !== 2 ||
          !Number.isSafeInteger(sourceSequence) || sourceSequence < 1 ||
          !Array.isArray(references) || references.length < 1 || references.length > 8 ||
          !Array.from(references).every(validReference) ||
          new Set(references.map(reference => reference.alias)).size !== references.length) {
        stop('invalid primary batch mint arguments');
        throw TypeError(stopped);
      }
      return caller.call('interface_guarded_mint_many', {
        source_sequence: sourceSequence, references: structuredClone(references)
      });
    },
    async observe(...unexpected) {
      if (unexpected.length || !observationArguments ||
          typeof observationArguments !== 'object' || Array.isArray(observationArguments)) {
        stop('invalid primary observation arguments');
        throw TypeError(stopped);
      }
      return caller.call(route === 'guarded-local' ? 'interface_guarded_observe' :
        'interface_observe', structuredClone(observationArguments));
    },
    async call(tool, args, controlId = null) {
      if (stopped && tool !== 'interface_close') throw Error('trial stopped: ' + stopped);
      if (!tools.has(tool)) {
        stop('unavailable tool ' + tool);
        throw Error(stopped); // Local rejection before host dispatch.
      }
      if (tool === 'interface_guarded_input' && args?.interaction !== undefined &&
          !['click', 'keyboard', 'move'].includes(args.interaction)) {
        stop('invalid guarded interaction');
        throw TypeError(stopped); // Match the public MCP enum before dispatch.
      }
      const expected = controlId === null ? null : controls.get(controlId);
      if (controlId !== null) {
        if (consumed.has(controlId)) { stop('control already consumed'); throw Error(stopped); }
        if (!expected || expected.tool !== tool || canonical(expected.args) !== canonical(args)) {
          stop('control request mismatch'); throw Error(stopped);
        }
        consumed.add(controlId);
      }
      let reply;
      try { reply = await host.sendPresented(tool, args, sinks); }
      catch (error) { stop('transport or presentation failure'); throw error; }
      try {
        if (reply.result.isError === true && !expected) {
          stop('unexpected MCP refusal');
          return reply; // Framework errors may contain free text, not typed JSON.
        }
        const meta = read(reply);
        const declaredRefusal = expected && reply.result.isError === true && meta.status === 'refused' &&
          meta.replay_allowed === false && meta.session?.binding_revision === expected.revision &&
          meta.session?.recovery_required === false && (expected.kind === 'source'
            ? meta.input_dispatched === false && meta.error === expected.error
            : meta.result?.input_dispatched === false && !meta.result.execution &&
              meta.result.guard_checks?.length === 1 && meta.result.guard_checks[0].stage === 'before_admission' &&
              meta.result.guard_checks[0].status === 'MISSING' && meta.result.guard_checks[0].reason === expected.reason &&
              meta.result.guard_checks[0].handle === expected.alias);
        if (expected && !declaredRefusal) stop('control outcome mismatch');
        if (reply.result.isError && !declaredRefusal) stop('unexpected MCP refusal');
        if (!declaredRefusal && tool === 'interface_guarded_mint_many') {
          // Registration can partially mutate the server store. Keep its original
          // response, but never continue input or retry an uncertain batch.
          if (meta.status !== 'minted' || meta.source_sequence !== args?.source_sequence ||
              !Array.isArray(args?.references) || !Array.isArray(meta.minted) ||
              meta.minted.length !== args.references.length ||
              meta.minted.some((reference, index) => reference?.alias !== args.references[index]?.alias)) {
            stop('incomplete or inconsistent batch mint result');
          }
        }
        if (!declaredRefusal && (tool === 'interface_guarded_input' || tool === 'interface_dispatch')) {
          const summary = tool === 'interface_dispatch' && meta.schema === 'agent-interface/review-v1' &&
            meta.receipt?.schema === 'agent-interface/receipt-view-dispatch-summary-v1';
          const execution = summary ? meta.receipt.execution_summary : meta.result?.execution;
          const releases = execution?.releases;
          const completed = summary ? meta.outcome_summary?.execution_status === 'completed' &&
            meta.outcome_summary.input_release_verified === true && meta.outcome_summary.recovery_required === false &&
            meta.outcome_summary.error === null : meta.status === 'completed';
          if (!completed || meta.image_status !== 'image' || !releases?.length ||
              releases.some(r => r.verified !== true || r.keys_down?.length !== 0 || r.buttons_down?.length !== 0)) {
            stop('incomplete input or unverified neutral release');
          }
          if (tool === 'interface_guarded_input' && args?.feedback !== undefined) {
            const cue = meta.feedback;
            if (cue?.status !== 'matched' || cue.expected_title !== args.feedback.expected_title ||
                canonical(cue.rejected_titles) !== canonical(args.feedback.rejected_titles ?? []) ||
                cue.title !== cue.expected_title || cue.after_title !== cue.title ||
                cue.task_success !== null || cue.authority_granted !== false || cue.input_dispatched !== false) {
              stop('missing or inconsistent requested feedback');
            }
          }
        }
        // Return the original response even after latching STOP. The primary must
        // receive its text/image evidence; the next ordinary call is prohibited.
        return reply;
      } catch (error) {
        // sendPresented already delivered the original evidence. Extraction or
        // outcome validation must fail closed before the primary can catch it.
        stop('response extraction or validation failure');
        throw error;
      }
    },
    async presentOriginal(...values) {
      const [attempt] = values;
      let callbacks;
      try { callbacks = { text: sinks?.text, image: sinks?.image }; }
      catch (error) { stop('original presentation sink snapshot failure'); throw error; }
      if (values.length !== 1 || !Number.isSafeInteger(attempt) || attempt < 1 ||
          typeof callbacks.text !== 'function' || typeof callbacks.image !== 'function') {
        stop('invalid original presentation arguments or sinks');
        throw TypeError('invalid original presentation arguments or sinks');
      }
      // Local original evidence only, never a new observation or tool request.
      // The host checks the retained reply's identity and enforces its own STOP.
      try { return await host.present(attempt, callbacks, { forceImage: true }); }
      catch (error) { stop('original presentation failure'); throw error; }
    },
    async acknowledgeText(attempt, attribution) {
      if (!Number.isSafeInteger(attempt) || attempt < 1 ||
          !['task', 'phase', 'reason'].every(k => typeof attribution?.[k] === 'string' && attribution[k].trim())) {
        stop('invalid primary acknowledgment arguments');
        throw TypeError(stopped);
      }
      try { return await host.acknowledgeText(attempt, attribution); }
      catch (error) { stop('text acknowledgment recording failure'); throw error; }
    },
    async review(attempt, review) {
      if (!Number.isSafeInteger(attempt) || attempt < 1 ||
          !['task', 'phase', 'reason'].every(k => typeof review?.[k] === 'string' && review[k].trim())) {
        stop('invalid primary review arguments');
        throw TypeError(stopped); // Do not poison the underlying evidence host.
      }
      try { return await host.review(attempt, review); }
      catch (error) { stop('review recording failure'); throw error; }
    }
  };
  return caller;
}

/** Opt-in host instrumentation. No model, task policy, input retry or action queue. */
import { readFile, writeFile, appendFile } from 'node:fs/promises';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { performance } from 'node:perf_hooks';
import { createRelayClient, presentRelayResponse, recordRelayReview } from './relay_client.mjs';

export async function createInstrumentedRelayClient(options) {
  const reuseImages = options.reuseReviewedImages ?? false;
  if (typeof reuseImages !== 'boolean') throw new TypeError('reuseReviewedImages must be boolean');
  const evidenceDirectory = options.evidenceDirectory;
  const client = await createRelayClient(options);
  const eventsPath = join(evidenceDirectory, 'host-events.jsonl');
  try { await writeFile(eventsPath, '', { flag: 'wx' }); }
  catch (error) { await client.close(); throw error; }
  let sequence = 0, busy = null, blocked = null, pending = null, closed = false, reservation = null;
  const delivered = new Map();
  const completedPresentations = new Map();
  // One bounded, explicitly reviewed PNG base, scoped to this live host instance.
  // Equality is byte-for-byte encoded PNG equality, never a hash/perceptual gate.
  let imageBase = null, lastPresentation = null;
  function singlePng(reply) {
    const images = reply.result?.content?.filter(block => block.type === 'image') ?? [];
    if (reply.status !== 'returned' || images.length !== 1) return null;
    const block = images[0];
    if (block.mimeType !== 'image/png' || typeof block.data !== 'string' ||
        block.data.length > 16 * 1024 * 1024) return null;
    const bytes = Buffer.from(block.data, 'base64');
    if (!bytes.length || bytes.toString('base64') !== block.data) return null;
    return { data: block.data, mime_type: block.mimeType,
      image_sha256: createHash('sha256').update(bytes).digest('hex') };
  }
  const event = async (kind, fields = {}) => {
    const row = { schema: 'agent-interface/relay-host-event-v1', sequence: ++sequence,
      host_monotonic_ms: performance.now(), kind, ...fields };
    await appendFile(eventsPath, JSON.stringify(row) + '\n');
    return row;
  };
  function begin(kind, reservationToken = null) {
    if (busy || (reservation && reservation !== reservationToken)) throw new Error('host operation outstanding; wait, do not queue or resend');
    if (blocked || closed) throw new Error(blocked || 'instrumented client closed');
    busy = kind;
  }
  function failed(error) {
    imageBase = null; lastPresentation = null;
    blocked = String(error) + '; host evidence incomplete: reconcile retained files; never infer no input or replay';
    throw new Error(blocked, { cause: error });
  }
  async function retained(attempt) {
    if (!Number.isSafeInteger(attempt) || !delivered.has(attempt)) throw new Error('explicit delivered attempt required');
    const replyPath = join(evidenceDirectory, `reply-${attempt}.json`);
    const bytes = await readFile(replyPath);
    const reply_sha256 = createHash('sha256').update(bytes).digest('hex');
    if (reply_sha256 !== delivered.get(attempt)) throw new Error('retained bytes differ from original delivered reply');
    return { replyPath, reply: JSON.parse(bytes), reply_sha256 };
  }
  function send(tool, args = {}, reservationToken = null) {
      begin('send', reservationToken);
      // Snapshot synchronously, before the instrumentation's asynchronous write.
      let snapshot;
      try {
        snapshot = JSON.parse(JSON.stringify(args, (_key, value) => {
          if (value === undefined || typeof value === 'function' || typeof value === 'symbol' ||
              (typeof value === 'number' && !Number.isFinite(value))) throw new TypeError('finite JSON required');
          return value;
        }));
        if (typeof tool !== 'string' || !snapshot || Array.isArray(snapshot) || typeof snapshot !== 'object') throw new TypeError('tool and argument object required');
      } catch (error) { busy = null; throw error; }
      const attempt = client.state().attempts + 1;
      pending = (async () => {
        try {
          await event('send_requested', { attempt, tool });
          const reply = await client.send(tool, snapshot);
          const bytes = await readFile(join(evidenceDirectory, `reply-${attempt}.json`));
          await event('reply_available', { attempt, tool, relay_id: reply.id ?? null,
            reply_sha256: createHash('sha256').update(bytes).digest('hex') });
          delivered.set(attempt, createHash('sha256').update(bytes).digest('hex'));
          // Host-only identity; persisted relay bytes and protocol IDs stay unchanged.
          return { ...reply, attempt };
        } catch (error) { return failed(error); }
        finally { busy = null; }
      })();
      pending.catch(() => {});
      return pending;
    }
  async function present(attempt, callbacks, { forceImage = false } = {}, reservationToken = null) {
      if (typeof forceImage !== 'boolean') throw new TypeError('forceImage must be boolean');
      begin('present', reservationToken);
      try {
        const saved = await retained(attempt);
        const picture = reuseImages ? singlePng(saved.reply) : null;
        if (forceImage) imageBase = null;
        const delivery = reuseImages && picture && imageBase &&
            picture.mime_type === imageBase.mime_type && picture.data === imageBase.data
          ? { mode: 'reviewed-image-reference', base_attempt: imageBase.attempt,
              base_reply_sha256: imageBase.reply_sha256, base_review_sha256: imageBase.review_sha256,
              image_sha256: picture.image_sha256, mime_type: picture.mime_type }
          : { mode: 'full' };
        const extra = reuseImages ? { image_delivery: delivery } : {};
        await event('presentation_started', { attempt, reply_sha256: saved.reply_sha256, ...extra });
        const selectedCallbacks = delivery.mode === 'reviewed-image-reference'
          ? { text: callbacks.text, image: async () => callbacks.text({
              schema: 'agent-interface/reviewed-image-reference-v1', attempt,
              reply_sha256: saved.reply_sha256, ...delivery,
              scope: 'Same PNG bytes as the explicitly reviewed base. Current reply metadata is separate; no redraw or task-completion inference.' }) }
          : callbacks;
        await presentRelayResponse(saved.reply, selectedCallbacks);
        await event('presentation_callbacks_completed', { attempt, reply_sha256: saved.reply_sha256, ...extra });
        completedPresentations.set(attempt, saved.reply_sha256);
        if (reuseImages) {
          if (delivery.mode === 'full') imageBase = null;
          lastPresentation = { attempt, reply_sha256: saved.reply_sha256, picture, delivery };
        }
      } catch (error) { return failed(error); }
      finally { busy = null; }
    }
  return {
    send(tool, args = {}) { return send(tool, args); },
    sendPresented(tool, args, callbacks) {
      const sinks = { text: callbacks?.text, image: callbacks?.image };
      if (typeof sinks.text !== 'function' || typeof sinks.image !== 'function') {
        throw new TypeError('text and image callbacks required before dispatch');
      }
      begin('send_presented');
      const token = Symbol('send_presented');
      busy = null; reservation = token;
      const combined = (async () => {
        try {
          const reply = await send(tool, args, token);
          await present(reply.attempt, sinks, {}, token);
          return reply;
        } finally { reservation = null; }
      })();
      pending = combined;
      pending.catch(() => {});
      return pending;
    },
    wait() {
      if (!pending) throw new Error('no request to reconcile');
      return pending;
    },
    present(attempt, callbacks, options) { return present(attempt, callbacks, options); },
    async acknowledgeText(attempt, { task, phase, reason } = {}) {
      if (![task, phase, reason].every(value => typeof value === 'string' && value.trim())) {
        throw new TypeError('nonempty task, phase and reason required');
      }
      begin('acknowledge_text');
      try {
        const saved = await retained(attempt);
        if (completedPresentations.get(attempt) !== saved.reply_sha256) {
          throw new Error('completed presentation of the unchanged reply required');
        }
        const reply = saved.reply;
        const content = reply.result?.content;
        if (reply.status !== 'returned' || !Number.isSafeInteger(reply.id) ||
            !Array.isArray(content) || !content.length ||
            !content.every(block => block?.type === 'text' && typeof block.text === 'string')) {
          throw new Error('returned text-only content required; use image review for images');
        }
        if (Object.hasOwn(reply.result, 'isError') && typeof reply.result.isError !== 'boolean') {
          throw new TypeError('isError must be boolean when present');
        }
        const receipt = { schema: 'agent-interface/text-acknowledgment-v1',
          task, phase, reason, recorded_at: new Date().toISOString(), attempt,
          relay_id: reply.id, tool: reply.tool, reply_sha256: saved.reply_sha256,
          text_blocks: content.length,
          ...(Object.hasOwn(reply.result, 'isError') ? { isError: reply.result.isError } : {}),
          evidence_scope: 'Caller attribution to presented original text only. No image review, semantic comprehension, input authority, task success or model-latency inference.' };
        await writeFile(join(evidenceDirectory, `text-acknowledgment-${attempt}.json`),
          JSON.stringify(receipt) + '\n', { flag: 'wx' });
        await event('text_acknowledgment_recorded', { attempt, reply_sha256: saved.reply_sha256,
          relay_id: reply.id, tool: reply.tool, task, phase });
        return receipt;
      } catch (error) { return failed(error); }
      finally { busy = null; }
    },
    async review(attempt, { task, phase, reason }) {
      begin('review');
      try {
        const saved = await retained(attempt);
        const receipt = await recordRelayReview({ replyPath: saved.replyPath,
          receiptPath: join(evidenceDirectory, `review-${attempt}.json`), task, phase, reason });
        const presented = reuseImages && lastPresentation?.attempt === attempt &&
          lastPresentation.reply_sha256 === saved.reply_sha256 ? lastPresentation : null;
        await event('review_recorded', { attempt, reply_sha256: receipt.reply_sha256,
          call_id: receipt.call_id, source_sequence: receipt.source_sequence, task, phase,
          ...(reuseImages ? { image_delivery: presented?.delivery ?? null } : {}) });
        if (presented?.picture && presented.delivery.mode === 'full') {
          const reviewBytes = await readFile(join(evidenceDirectory, `review-${attempt}.json`));
          imageBase = { ...presented.picture, attempt, reply_sha256: saved.reply_sha256,
            review_sha256: createHash('sha256').update(reviewBytes).digest('hex') };
        }
        return receipt;
      } catch (error) { return failed(error); }
      finally { busy = null; }
    },
    state() { return { ...client.state(), host_busy: busy ?? (reservation ? 'send_presented' : null), host_blocked: blocked, host_closed: closed, event_sequence: sequence }; },
    async close() {
      if (busy || reservation) throw new Error('host operation outstanding; cannot close');
      if (closed) throw new Error('instrumented client already closed');
      busy = 'close';
      try {
        // Always permit transport cleanup after an instrumentation failure.
        const result = await client.close(); closed = true; imageBase = null; lastPresentation = null;
        await event('transport_closed', { code: result.code, signal: result.signal });
        return result;
      } catch (error) { return failed(error); }
      finally { busy = null; }
    },
  };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {PassThrough,Writable} from 'node:stream';
import {mkdtemp,readFile} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {createPrimaryExchange} from './primary_exchange.mjs';
import {servePrimaryLines,validatePrimaryConfig,runPrimaryStdio} from './primary_stdio.mjs';

function setup(execute) {
  const input=new PassThrough(),output=new PassThrough();let bytes='';
  output.on('data',chunk=>{bytes+=chunk});
  let next=1;
  const exchange={state:()=>({next_id:next}),execute:async request=>{next++;return execute(request);}};
  return {input,output,exchange,rows:()=>bytes.trim().split('\n').filter(Boolean).map(JSON.parse)};
}
test('numbered commands return exact file/text descriptors with no image encoding',async()=>{
  const value={id:1,attempt:3,presented_text:['original metadata',{isError:false}],
    images:[{path:'/original.png',sha256:'abc',bytes:4,mime_type:'image/png'}]};
  const s=setup(async()=>value);const pending=servePrimaryLines(s);
  s.input.end('{"id":1,"method":"observe","args":[]}\n');await pending;
  assert.deepEqual(s.rows()[0],{schema:'agent-interface/primary-stdio-v1',status:'returned',result:value});
});
test('commands arriving while outstanding are rejected rather than queued',async()=>{
  let release,calls=0;const s=setup(async()=>{calls++;await new Promise(r=>{release=r;});return {id:1};});
  const pending=servePrimaryLines(s);s.input.write('{"id":1}\n');
  while(!release)await new Promise(r=>setImmediate(r));
  s.input.write('{"id":2}\n');await new Promise(r=>setImmediate(r));
  assert.equal(calls,1);assert.equal(s.rows()[0].status,'busy');assert.equal(s.rows()[0].operation_invoked,false);
  release();s.input.end();await pending;assert.equal(calls,1);
  assert.equal(s.rows()[1].status,'returned');
});
test('EOF waits for the already committed command without replaying it',async()=>{
  let release,calls=0;const s=setup(async()=>{calls++;await new Promise(r=>{release=r;});return {id:1};});
  let ended=false;const pending=servePrimaryLines(s).then(()=>{ended=true;});
  s.input.write('{"id":1}\n');while(!release)await new Promise(r=>setImmediate(r));
  s.input.end();await new Promise(r=>setImmediate(r));assert.equal(ended,false);
  release();await pending;assert.equal(calls,1);assert.equal(s.rows().length,1);
});
test('malformed JSON is refused without invoking exchange or consuming a command',async()=>{
  let calls=0;const s=setup(async()=>{calls++;return {id:1};});const pending=servePrimaryLines(s);
  s.input.write('{invalid\n');await new Promise(r=>setImmediate(r));
  assert.equal(calls,0);assert.equal(s.rows()[0].status,'refused');assert.equal(s.rows()[0].next_id,1);
  s.input.end('{"id":1}\n');await pending;assert.equal(calls,1);
});
test('command error reports uncertainty and state without retry',async()=>{
  let calls=0;const s=setup(async()=>{calls++;throw Error('reply write failed after input');});
  const pending=servePrimaryLines(s);s.input.end('{"id":1}\n');await pending;
  const row=s.rows()[0];assert.equal(row.status,'command_error');assert.equal(row.replay_allowed,false);
  assert.match(row.error,/after input/);assert.equal(calls,1);assert.equal(row.state.next_id,2);
});
test('output failure rejects the stream owner after one completed command',async()=>{
  const input=new PassThrough();let calls=0;
  const output=new Writable({write(_chunk,_encoding,callback){callback(Error('sink unavailable'));}});
  const exchange={state:()=>({next_id:2}),execute:async()=>{calls++;return {id:1};}};
  const pending=servePrimaryLines({input,output,exchange});input.end('{"id":1}\n');
  await assert.rejects(pending,/sink unavailable/);assert.equal(calls,1);
});
const valid={host:{command:'/node',args:[],evidenceDirectory:'/evidence'},route:'guarded-local',exchangeDirectory:'/exchange'};
test('config refuses unknown routes and fields before starting a host',()=>{
  assert.deepEqual(validatePrimaryConfig(valid),valid);
  for(const config of [{...valid,route:'typo'},{...valid,extra:true},{...valid,host:{...valid.host,shell:true}},
    {...valid,host:{...valid.host,args:[null]}},{...valid,exchangeDirectory:''}])
    assert.throws(()=>validatePrimaryConfig(config));
});

test('terminal output refuses before starting a relay or allocating its evidence',async()=>{
  const output=new PassThrough();output.isTTY=true;
  await assert.rejects(runPrimaryStdio(valid,{input:new PassThrough(),output}),/stdout must be a pipe or file/);
});

test('startup output failure keeps original exception, closes one relay and never writes again',async()=>{
  const root=await mkdtemp(join(tmpdir(),'primary-stdio-output-'));
  const error=Error('original startup output failure');let writes=0;
  const output=new Writable({write(_chunk,_encoding,callback){writes++;callback(error);}});
  output.on('error',()=>{});
  const config={host:{command:process.execPath,args:['-e','process.stdin.resume()'],evidenceDirectory:join(root,'host')},
    route:'guarded-local',exchangeDirectory:join(root,'exchange')};
  await assert.rejects(runPrimaryStdio(config,{input:new PassThrough(),output}),value=>value===error);
  assert.equal(writes,1);
  assert.deepEqual(JSON.parse(await readFile(join(root,'host/exit.json'))),{code:0,signal:null});
});


test('failed review is correlated to its consumed command without a host call or replay',async()=>{
  let hostCalls=0;
  const directory=join(await mkdtemp(join(tmpdir(),'primary-error-id-')),'exchange');
  const host={review:async()=>{hostCalls++;},sendPresented:async()=>{hostCalls++;return {attempt:1,result:{isError:false,content:[{type:'text',text:'{"status":"closed"}'}]}};}};
  const exchange=await createPrimaryExchange({host,directory,route:'guarded-local'});
  const input=new PassThrough(),output=new PassThrough();let bytes='';
  output.on('data',chunk=>{bytes+=chunk;});
  const pending=servePrimaryLines({exchange,input,output});
  input.end(JSON.stringify({id:1,method:'review',args:[1,{image:{index:1}}]})+'\n');await pending;
  const row=JSON.parse(bytes.trim());
  assert.equal(row.status,'command_error');assert.equal(row.command_id,1);
  assert.equal(row.command_method,'review');assert.equal(row.state.next_id,2);
  assert.equal(row.replay_allowed,false);assert.ok(row.state.stopped);assert.equal(hostCalls,0);
  await assert.rejects(exchange.execute({id:2,method:'observe',args:[]}),/exchange stopped/);
  assert.equal(hostCalls,0);
  await exchange.execute({id:2,method:'call',args:['interface_close',{}]});assert.equal(hostCalls,1);
});
test('pre-admission envelope error keeps requested id distinct from unconsumed next id',async()=>{
  const directory=join(await mkdtemp(join(tmpdir(),'primary-invalid-id-')),'exchange');
  const exchange=await createPrimaryExchange({host:{},directory,route:'guarded-local'});
  const input=new PassThrough(),output=new PassThrough();let bytes='';output.on('data',chunk=>{bytes+=chunk;});
  const pending=servePrimaryLines({exchange,input,output});
  input.end(JSON.stringify({id:9,method:'observe',args:[]})+'\n');await pending;
  const row=JSON.parse(bytes.trim());assert.equal(row.status,'command_error');
  assert.equal(row.command_id,9);assert.equal(row.command_method,'observe');
  assert.equal(row.state.next_id,1);assert.equal(row.state.stopped,null);
});
test('malformed command identity stays bounded and does not become a valid correlation',async()=>{
  const s=setup(async()=>{throw Error('invalid envelope');});const pending=servePrimaryLines(s);
  s.input.end(JSON.stringify({id:{not:'number'},method:'x'.repeat(1000)})+'\n');await pending;
  const row=s.rows()[0];assert.equal(row.status,'command_error');
  assert.equal(row.command_id,null);assert.equal(row.command_method,null);assert.equal(row.replay_allowed,false);
});
